export const getComputeReconstructionRoiTracesUrl = (reconstructionId: number,
    pointId: string,) => {




  return `/api/v1/reconstruction-runs/${reconstructionId}/points/${pointId}/roi-traces`
}

/**
 * One trace per square ROI of a complete point, in the request's order, against the depth (µm) and the depth
 * index, as lauelab's `plot_roi_traces` plots them: the sum of the ROI's stored pixels at each depth, or with
 * `normalize` that divided by its own maximum (a trace whose maximum is not positive has no values, and the
 * reason). Each square is centred as near as it can be to `x`, `y`: never clipped or
 * shifted, so one that would extend outside the image is a 422 naming it (`["rois", i]`), and nothing is read. At
 * most 32 ROIs. Each ROI's trace is kept: those not computed yet are computed together, in one pass over the
 * point's frames, which waits for a turn, as the trace. Reads only. Otherwise the frames' errors.
 *
 * Needs the header `X-Laue-Portal: 1`, as every request that changes data (the portal's pages send it; scripts must too). Without it, or from a page on another origin (a `Sec-Fetch-Site` other than `same-origin` or `none`), the answer is a 403 problem and nothing changes.
 * @summary Compute a point's ROI traces
 */
export const computeReconstructionRoiTraces = async (reconstructionId: number,
    pointId: string,
    reconstructionRoiTracesRequest: ReconstructionRoiTracesRequest, options?: Parameters<typeof apiFetch>[1]): Promise<ReconstructionRoiTraces> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<ReconstructionRoiTraces>(getComputeReconstructionRoiTracesUrl(reconstructionId,pointId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(reconstructionRoiTracesRequest)
  }
);}





